-- =====================================================================
-- STEP 1 / 2 : スキーマ更新（受取時間の列を追加）
--
-- 受取時間の選択機能で使う列を追加します。既存データには触れません。
-- 最後の INSERT は drizzle の適用済み記録です。これを入れておくと、
-- 今後 db:migrate を流したときに二重適用になりません。
-- =====================================================================
BEGIN;

ALTER TABLE "events" ADD COLUMN "pickup_time_slots" text DEFAULT '' NOT NULL;
ALTER TABLE "orders" ADD COLUMN "pickup_time_slot" text;

VALUES ('02549cf5b0093388bce5177b0f0843a03241c10610428c7e857e9d0a9033138f', 1790571240713);

COMMIT;


-- =====================================================================
-- STEP 2 / 2 : ゲゲゲ忌コラボ 本番データ
-- ご記入シート（2026-09-28 時点）の内容で、イベント・受取日・商品・
-- 受付枠をまるごと入れ替えます。
--
-- 既存の予約がある場合は中断します（消さないための保険です）。
-- =====================================================================
BEGIN;

-- 予約が1件でもあれば、ここで失敗させて中断する。
DO $$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM orders;
  IF n > 0 THEN
    RAISE EXCEPTION '既存の予約が % 件あります。入れ替える前に内容を確認してください。', n;
  END IF;
END $$;

-- 子テーブルから順に消す。
DELETE FROM order_items;
DELETE FROM orders;
DELETE FROM daily_product_inventory;
DELETE FROM event_dates;
DELETE FROM products;
DELETE FROM events;

